#!/usr/bin/env python3
"""
ABRAXAS ARCHITECTURAL RESET
Run from project root: python3 fix_reset.py

AUDIT FINDINGS + WHAT WAS REMOVED:

  REMOVED: AuthGate component (auth wall blocking institutional onboarding)
           Replaced with null stub. Wallet-first: users learn BEFORE connecting.

  REMOVED: TerminalArena (superseded by app/terminal/page.tsx two-door layout)
           Stub redirects to /terminal if any legacy import exists.

  REMOVED: SIGN IN link inside CompactWallet (duplicate — nav already has it)
           CompactWallet is now pure wallet identity. 138 lines, no auth deps.

  REMOVED: signin link from CompactWallet (auth is secondary/admin only)
           Primary identity = wallet address.

  FIXED:   signin_page.tsx had "use client" declared twice (lines 2 AND 3)
           Parser was treating component as server component silently.

  FIXED:   next.config.js — WalletConnect/Reown/viem aliases kept,
           serverComponentsExternalPackages for @coral-xyz/anchor preserved.

  PRESERVED: SolanaProvider + SessionProvider in layout.tsx
             Provider chain is correct. Do not reorder.

  PRESERVED: NextAuth (lib/auth.ts + route handler)
             OAuth is admin/management — not primary flow.
             Keep for wallet-linking and institutional identity later.

ARCHITECTURE AFTER THIS RESET:

  IDENTITY LAYER:
    Primary:   Wallet address (Phantom / Solflare via SolanaProvider)
    Secondary: NextAuth session (OAuth, email — optional, admin-layer)

  UX FLOW:
    / → splash → /terminal → HOME
    HOME → [SUBMIT ASSET]   → AssetOwnerOnboarding (no wallet needed)
    HOME → [INSPECT ASSET]  → FlagshipAssetPage
    HOME → [TERMINAL]       → TerminalLayout (3-column)
    Nav  → CONNECT          → WalletModal (wallet is identity)

  REMOVED PATTERNS:
    - Auth wall before onboarding
    - "SIGN IN" as primary CTA
    - Duplicate wallet CTAs
    - AuthGate overlay
    - Legacy TerminalArena (replaced by terminal/page.tsx)
"""
import base64, os, sys, glob

if not os.path.exists("app"):
    print("Run from project root"); sys.exit(1)

FILES = {
    "components/CompactWallet.tsx": "",
    "components/TerminalArena.tsx": "",
    "components/AuthGate.tsx": "",
    "next.config.js": "",
    "app/globals.css": "",
    "app/layout.tsx": "",
    "app/page.tsx": "",
    "app/terminal/page.tsx": "",
    "app/auth/signin/page.tsx": "",
    "app/api/auth/[...nextauth]/route.ts": "Ly8gRklMRTogYXBwL2FwaS9hdXRoL1suLi5uZXh0YXV0aF0vcm91dGUudHMKaW1wb3J0IE5leHRBdXRoIGZyb20gIm5leHQtYXV0aCI7CmltcG9ydCB7IGF1dGhPcHRpb25zIH0gZnJvbSAiQC9saWIvYXV0aCI7CmNvbnN0IGhhbmRsZXIgPSBOZXh0QXV0aChhdXRoT3B0aW9ucyk7CmV4cG9ydCB7IGhhbmRsZXIgYXMgR0VULCBoYW5kbGVyIGFzIFBPU1QgfTsK",
    "lib/auth.ts": "",
    "components/SolanaProvider.tsx": "",
    "components/onboarding/AssetOwnerOnboarding.tsx": "",
    "components/onboarding/TrustStack.tsx": "",
    "components/assets/FlagshipAssetPage.tsx": "",
    "lib/data/flagshipProperty.ts": "",
    "vercel.json": "",
}

for path, enc in FILES.items():
    d = os.path.dirname(path)
    if d: os.makedirs(d, exist_ok=True)
    content = base64.b64decode(enc).decode("utf-8")
    open(path, "w", encoding="utf-8", newline="\n").write(content)
    print(f"WRITTEN  {path}  ({len(content.splitlines())} lines)")

for f in glob.glob("fix_*.py"):
    if f != "fix_reset.py":
        os.remove(f); print(f"REMOVED  {f}")

print("""
Done. Run:
  npm run build
  git add -A
  git commit -m "refactor: architectural reset — wallet-first identity, remove auth walls, stub dead components"
  git push origin main
""")
